// graphql-cost-guard.js
const DEFAULT_MAX_DEPTH = 7;
const DEFAULT_MAX_COST  = 1000;

/**
 * Walk the SelectionSet and sum field costs.
 * List fields are identified by a `cost` hint on field extensions.
 */
function computeCost(selectionSet, typeDef, schema) {
  if (!selectionSet) return 0;
  let total = 0;
  for (const selection of selectionSet.selections) {
    if (selection.kind === 'Field') {
      const fieldDef = typeDef?.getFields()[selection.name.value];
      const fieldCost = fieldDef?.extensions?.cost ?? 1;
      total += fieldCost;
      total += computeCost(
        selection.selectionSet,
        getNamedType(schema, fieldDef),
        schema
      );
    }
  }
  return total;
}

function depthOf(selectionSet, depth = 0) {
  if (!selectionSet?.selections?.length) return depth;
  let max = depth;
  for (const sel of selectionSet.selections) {
    if (sel.kind === 'Field') {
      const d = depthOf(sel.selectionSet, depth + 1);
      if (d > max) max = d;
    }
  }
  return max;
}

function getNamedType(schema, fieldDef) {
  let t = fieldDef?.type;
  while (t?.ofType) t = t.ofType;
  return t ? schema.getType(t.name) : null;
}

export function complexityGuard(
  { maxDepth = DEFAULT_MAX_DEPTH, maxCost = DEFAULT_MAX_COST } = {}
) {
  return (context) => ({
    Document(node) {
      for (const def of node.definitions) {
        if (def.kind !== 'OperationDefinition') continue;

        const depth = depthOf(def.selectionSet);
        if (depth > maxDepth) {
          context.reportError(
            new GraphQLError(`Query depth ${depth} exceeds max ${maxDepth}`)
          );
        }

        const queryType = context.getSchema().getQueryType();
        const cost = computeCost(
          def.selectionSet, queryType, context.getSchema()
        );
        if (cost > maxCost) {
          context.reportError(
            new GraphQLError(`Query cost ${cost} exceeds budget ${maxCost}`)
          );
        }
      }
    },
  });
}

import DataLoader from 'dataloader';
import { db } from './db.js';

export function makeUserLoader() {
  return new DataLoader(async (ids) => {
    const rows = await db.query(
      'SELECT * FROM users WHERE id = ANY($1)', [ids]
    );
    const map = Object.fromEntries(rows.map(r => [r.id, r]));
    return ids.map(id => map[id] ?? null);
  });
}

export function makeOrgLoader() {
  return new DataLoader(async (orgIds) =>
    Promise.all(
      orgIds.map(id =>
        db.query('SELECT * FROM orgs WHERE id = $1', [id]).then(r => r[0] ?? null)
      )
    )
  );
}
